#include <string>
#include <vector>

class Solution {
public:
    std::string sortString(std::string s) {
        std::vector<int> counts(26, 0);
        for (char ch : s) counts[ch - 'a']++;
        std::string res = "";
        int total = s.size();
        while ((int)res.size() < total) {
            for (int i = 0; i < 26; ++i) {
                if (counts[i] > 0) {
                    res += (char)('a' + i);
                    counts[i]--;
                }
            }
            for (int i = 25; i >= 0; --i) {
                if (counts[i] > 0) {
                    res += (char)('a' + i);
                    counts[i]--;
                }
            }
        }
        return res;
    }
};

class Solution {
    public String sortString(String s) {
        int[] counts = new int[26];
        for (char ch : s.toCharArray()) counts[ch - 'a']++;
        StringBuilder sb = new StringBuilder();
        int total = s.length();
        while (sb.length() < total) {
            for (int i = 0; i < 26; i++) {
                if (counts[i] > 0) {
                    sb.append((char)('a' + i));
                    counts[i]--;
                }
            }
            for (int i = 25; i >= 0; i--) {
                if (counts[i] > 0) {
                    sb.append((char)('a' + i));
                    counts[i]--;
                }
            }
        }
        return sb.toString();
    }
}

var sortString = function(s) {
    const counts = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) counts[s.charCodeAt(i) - 97]++;
    const res = [];
    while (res.length < s.length) {
        for (let i = 0; i < 26; i++) {
            if (counts[i] > 0) {
                res.push(String.fromCharCode(97 + i));
                counts[i]--;
            }
        }
        for (let i = 25; i >= 0; i--) {
            if (counts[i] > 0) {
                res.push(String.fromCharCode(97 + i));
                counts[i]--;
            }
        }
    }
    return res.join("");
};
